const item = $input.first();
const question = item.json.body?.question ?? item.json.question ?? '';
const forced = (item.json.body?.variant ?? '').toLowerCase();
let variant;
if (forced === 'control') {
  variant = { k: 5, model_version: 'v0.1-openai-cosine-top5', variant: 'control' };
} else if (forced === 'canary') {
  variant = { k: 8, model_version: 'v0.2-openai-cosine-top8', variant: 'canary' };
} else {
  const r = Math.random();
  variant = r < 0.5
    ? { k: 5, model_version: 'v0.1-openai-cosine-top5', variant: 'control' }
    : { k: 8, model_version: 'v0.2-openai-cosine-top8', variant: 'canary' };
}
return [{
  json: {
    question,
    ...variant,
    start_ms: Date.now()
  }
}];

const picked = $('Pick Variant').first().json;
const chunks = $input.all().map(item => item.json);

const context = chunks.map((c, i) =>
  `[Source ${i + 1}, chunk_id=${c.id}]\n${c.content}`
).join('\n\n---\n\n');

const messages = [
  {
    role: 'system',
    content: 'You are a documentation assistant for the Cinder Analytics Platform. Answer the user\'s question using ONLY the provided context. If the answer is not in the context, say so explicitly. Cite source chunk IDs in square brackets, e.g. [chunk 42].'
  },
  {
    role: 'user',
    content: `Context:\n${context}\n\nQuestion: ${picked.question}`
  }
];

return [{
  json: {
    question: picked.question,
    variant: picked.variant,
    k: picked.k,
    model_version: picked.model_version,
    start_ms: picked.start_ms,
    retrieved_chunks: chunks.map(c => ({
      id: c.id,
      document_id: c.document_id,
      chunk_index: c.chunk_index,
      preview: String(c.content).slice(0, 200)
    })),
    messages
  }
}];

const composed = $('Compose Prompt').first().json;
const completion = $input.first().json;

const answer = completion.choices?.[0]?.message?.content ?? '';
const rawLatency = Date.now() - composed.start_ms;
const latencyMs = Math.max(0, Math.min(2147483647, Number.isFinite(rawLatency) ? rawLatency : 0));

return [{
  json: {
    question: composed.question,
    answer: answer,
    retrieved_chunks: JSON.stringify(composed.retrieved_chunks),
    chat_model: 'gpt-4o-mini',
    embedding_model: 'text-embedding-3-small',
    retrieval_k: composed.k,
    model_version: composed.model_version,
    latency_ms: latencyMs
  }
}];

